"""Arabic RTL storefront theme for UCHIHA STORE."""

STOREFRONT_HTML = r"""<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#08090d"><title>UCHIHA STORE</title><style>
:root{--b:#07080b;--p:#12151c;--p2:#191d27;--l:#2a2f3b;--t:#f7f8fb;--m:#9da6b7;--r:#ed293d;--r2:#860d1a;--g:#34d399}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 90% -10%,#ed293d38,transparent 32%),var(--b);color:var(--t);font-family:Tahoma,Arial,sans-serif}button,input,select{font:inherit}.wrap{width:min(1180px,calc(100% - 24px));margin:auto}.top{position:sticky;top:0;z-index:30;background:#07080bdc;backdrop-filter:blur(16px);border-bottom:1px solid #ffffff12}.nav{min-height:74px;display:flex;align-items:center;gap:12px}.brand{display:flex;align-items:center;gap:10px;font-weight:900;white-space:nowrap}.logo{width:43px;height:43px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(145deg,var(--r),#590711);box-shadow:0 10px 28px #ed293d45}.brand small{display:block;color:var(--m);font-size:9px;letter-spacing:1.5px}.search{flex:1}.search input{width:100%;height:46px;padding:0 16px;border:1px solid var(--l);border-radius:14px;outline:0;background:#10131a;color:var(--t)}.search input:focus{border-color:var(--r);box-shadow:0 0 0 4px #ed293d18}.ctl{height:44px;border:1px solid var(--l);border-radius:13px;background:var(--p);color:var(--t);padding:0 13px;cursor:pointer}.cart{position:relative}.badge{position:absolute;top:-8px;left:-7px;min-width:21px;height:21px;border-radius:20px;display:grid;place-items:center;background:var(--r);font-size:11px}.hero{padding:44px 0 25px}.heroBox{min-height:310px;padding:42px;border:1px solid #ffffff14;border-radius:28px;background:linear-gradient(115deg,#ed293d35,#151821f2 48%,#0d0f15fa);box-shadow:0 24px 70px #0007;overflow:hidden;position:relative}.heroBox:after{content:"UCHIHA";position:absolute;left:-12px;bottom:-36px;font-size:132px;font-weight:900;color:#ffffff08;letter-spacing:10px}.pill{display:inline-block;padding:8px 12px;border:1px solid #ed293d55;border-radius:99px;background:#ed293d18;color:#ffb8bf;font-size:12px;font-weight:900}.hero h1{font-size:clamp(38px,6vw,68px);line-height:1.05;margin:17px 0 13px}.hero p{max-width:690px;color:#c5cbd6;font-size:16px;line-height:1.9}.row{display:flex;gap:10px;flex-wrap:wrap}.primary,.secondary{min-height:47px;padding:0 19px;border-radius:14px;font-weight:900;cursor:pointer}.primary{border:0;background:linear-gradient(135deg,var(--r),var(--r2));color:white}.secondary{border:1px solid #ffffff1c;background:#ffffff0d;color:white}.features{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:20px}.feature{padding:14px;border:1px solid #ffffff12;border-radius:15px;background:#ffffff08;color:#ccd1db}.feature b{display:block;color:white;margin-bottom:4px}.head{display:flex;justify-content:space-between;align-items:end;margin:29px 0 14px}.head h2{margin:0}.muted{color:var(--m);font-size:13px}.cats{display:flex;gap:9px;overflow:auto;padding-bottom:10px}.cat{white-space:nowrap;border:1px solid var(--l);border-radius:12px;background:#11141a;color:#d5d9e2;padding:10px 14px;cursor:pointer}.cat.on{background:linear-gradient(135deg,var(--r),var(--r2));border-color:transparent}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card{display:flex;flex-direction:column;min-height:320px;border:1px solid var(--l);border-radius:19px;overflow:hidden;background:linear-gradient(155deg,#171a23,#0f1117)}.pic{height:126px;display:grid;place-items:center;position:relative;background:radial-gradient(circle at 70% 20%,#ed293d4d,transparent 42%),#161922;font-size:40px;font-weight:900}.tag{position:absolute;right:10px;top:10px;padding:5px 7px;border:1px solid #ffffff1c;border-radius:9px;background:#08090dbb;font-size:10px}.body{display:flex;flex:1;flex-direction:column;gap:9px;padding:14px}.body h3{font-size:15px;line-height:1.55;margin:0}.desc{color:var(--m);font-size:12px;line-height:1.7;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.meta{display:flex;justify-content:space-between;align-items:center;margin-top:auto}.price{font-size:19px;font-weight:900}.stock{font-size:10px;color:var(--g)}.cardBtns{display:grid;grid-template-columns:1fr auto;gap:8px}.buy,.add{height:41px;border-radius:11px;font-weight:900;cursor:pointer}.buy{border:0;background:var(--r);color:#fff}.add{width:45px;border:1px solid var(--l);background:#242834;color:#fff}.empty{grid-column:1/-1;padding:45px 20px;text-align:center;border:1px dashed #343947;border-radius:17px;color:var(--m)}.more{text-align:center;padding:24px 0 50px}.more button{display:none}.overlay{position:fixed;inset:0;z-index:50;background:#000a;opacity:0;pointer-events:none;transition:.2s}.overlay.on{opacity:1;pointer-events:auto}.drawer{position:fixed;top:0;bottom:0;left:0;z-index:60;width:min(420px,93vw);display:flex;flex-direction:column;background:#0d0f14;border-right:1px solid var(--l);transform:translateX(-102%);transition:.25s}.drawer.on{transform:none}.dhead{height:72px;padding:0 17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--l)}.items{flex:1;overflow:auto;padding:14px}.item{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;margin-bottom:9px;border:1px solid var(--l);border-radius:13px;background:#151821}.item small{display:block;color:var(--m);margin-top:4px}.del{border:0;background:none;color:#ff7b87;cursor:pointer}.foot{padding:16px;border-top:1px solid var(--l)}.total{display:flex;justify-content:space-between;font-size:18px;font-weight:900;margin-bottom:12px}.wide{width:100%}.toast{position:fixed;z-index:80;bottom:20px;right:50%;transform:translate(50%,25px);padding:11px 16px;border:1px solid #3a404e;border-radius:12px;background:#20242e;opacity:0;transition:.2s}.toast.on{opacity:1;transform:translate(50%,0)}footer{padding:25px;border-top:1px solid #ffffff10;text-align:center;color:var(--m);font-size:12px}@media(max-width:900px){.grid{grid-template-columns:repeat(3,1fr)}.features{grid-template-columns:1fr}.nav{flex-wrap:wrap;padding:11px 0}.search{order:3;flex-basis:100%}}@media(max-width:640px){.grid{grid-template-columns:repeat(2,1fr);gap:9px}.hero{padding-top:20px}.heroBox{padding:25px 19px;min-height:270px}.brand small{display:none}.card{min-height:300px}}@media(max-width:380px){.grid{grid-template-columns:1fr}}
</style></head><body><header class="top"><div class="wrap nav"><div class="brand"><div class="logo">火</div><div><span id="name">UCHIHA STORE</span><small>DIGITAL MARKET</small></div></div><div class="search"><input id="q" placeholder="ابحث عن لعبة، بطاقة أو خدمة رقمية..."></div><select id="cur" class="ctl"></select><button id="cartOpen" class="ctl cart">السلة <span id="count" class="badge">0</span></button></div></header><main class="wrap"><section class="hero"><div class="heroBox"><span class="pill">● منتجات رقمية وتسليم سريع</span><h1>متجرك الرقمي،<br>بأسلوب UCHIHA.</h1><p>تصفّح المنتجات الحقيقية المتوفرة الآن، ثم افتح المنتج نفسه داخل بوت المتجر لإكمال الدفع والتسليم بأمان.</p><div class="row"><button id="browse" class="primary">تصفّح المنتجات</button><button id="telegram" class="secondary">فتح بوت المتجر</button></div><div class="features"><div class="feature"><b>كتالوج حي</b>الأسعار والمخزون من قاعدة المتجر</div><div class="feature"><b>شراء مباشر</b>فتح نفس المنتج داخل تيليجرام</div><div class="feature"><b>نظام موحد</b>الدفع والتسليم عبر UCHIHA</div></div></div></section><section id="products"><div class="head"><div><h2>أقسام المتجر</h2><span class="muted">اختر قسمًا أو استخدم البحث</span></div><span id="results" class="muted"></span></div><div id="cats" class="cats"></div><div class="head"><h2>المنتجات المتاحة</h2></div><div id="grid" class="grid"><div class="empty">جاري تحميل المتجر...</div></div><div class="more"><button id="more" class="secondary">عرض المزيد</button></div></section></main><footer>© <span id="year"></span> <span id="footName">UCHIHA STORE</span> — جميع الحقوق محفوظة</footer><div id="overlay" class="overlay"></div><aside id="drawer" class="drawer"><div class="dhead"><b>سلة المشتريات</b><button id="cartClose" class="ctl">إغلاق</button></div><div id="items" class="items"></div><div class="foot"><div class="total"><span>الإجمالي</span><span id="total">0</span></div><button id="checkout" class="primary wide">إكمال الطلب عبر تيليجرام</button></div></aside><div id="toast" class="toast"></div><script>
(()=>{'use strict';const API='/v1/storefront/public-catalog',S={cat:'',q:'',page:1,pages:0,busy:false,store:{name:'UCHIHA STORE',currency:'USD',exchange_rates:{USD:1},telegram_url:'https://t.me/UchihaStoreBot',accepting_orders:true},map:new Map(),cart:readCart(),cur:localStorage.getItem('uchiha_currency')||''},$=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),ini=x=>String(x||'U').trim().split(/\s+/).slice(0,2).map(v=>v[0]||'').join('').toUpperCase();function readCart(){try{let x=JSON.parse(localStorage.getItem('uchiha_cart')||'[]');return Array.isArray(x)?x:[]}catch{return[]}}function save(){localStorage.setItem('uchiha_cart',JSON.stringify(S.cart));renderCart()}function note(x){$('toast').textContent=x;$('toast').classList.add('on');clearTimeout(note.t);note.t=setTimeout(()=>$('toast').classList.remove('on'),2200)}function tg(id){let b=S.store.telegram_url||'https://t.me/UchihaStoreBot';try{let u=new URL(b);if(id)u.searchParams.set('start','product_'+id);return u.toString()}catch{return'https://t.me/UchihaStoreBot'+(id?'?start=product_'+id:'')}}function money(x){let code=S.cur||S.store.currency||'USD',rate=Number((S.store.exchange_rates||{})[code]||1),n=Number(x||0)*rate;try{return new Intl.NumberFormat('ar',{style:'currency',currency:code,maximumFractionDigits:2}).format(n)}catch{return n.toFixed(2)+' '+code}}function store(x){S.store={...S.store,...x};$('name').textContent=S.store.name;$('footName').textContent=S.store.name;document.title=S.store.name;let codes=Object.keys(S.store.exchange_rates||{[S.store.currency]:1});if(!codes.includes(S.cur))S.cur=S.store.currency||codes[0];$('cur').innerHTML=codes.map(c=>`<option ${c===S.cur?'selected':''}>${esc(c)}</option>`).join('')}function cats(a){$('cats').innerHTML=`<button class="cat ${S.cat?'':'on'}" data-cat="">كل المنتجات</button>`+a.filter(x=>+x.product_count>0).map(x=>`<button class="cat ${String(x.id)===S.cat?'on':''}" data-cat="${+x.id}">${esc(x.name)} (${+x.product_count})</button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{S.cat=b.dataset.cat;S.page=1;load(false)})}function card(p){S.map.set(+p.id,p);let ok=p.available&&S.store.accepting_orders;return`<article class="card"><div class="pic"><span class="tag">${esc(p.category_name||'منتجات رقمية')}</span>${esc(ini(p.name))}</div><div class="body"><h3>${esc(p.name)}</h3><div class="desc">${esc(p.description||'منتج رقمي متوفر عبر UCHIHA STORE.')}</div><div class="meta"><span class="price">${esc(money(p.price))}</span><span class="stock">${ok?'● متوفر الآن':'غير متاح'}</span></div><div class="cardBtns"><button class="buy" data-buy="${+p.id}" ${ok?'':'disabled'}>${ok?'شراء الآن':'غير متاح'}</button><button class="add" data-add="${+p.id}">🛒</button></div></div></article>`}function bind(){document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>window.open(tg(+b.dataset.buy),'_blank','noopener'));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(S.map.get(+b.dataset.add)))}async function load(append){if(S.busy)return;S.busy=true;if(!append)$('grid').innerHTML='<div class="empty">جاري تحميل المتجر...</div>';let p=new URLSearchParams({page:S.page,limit:24});if(S.cat)p.set('category_id',S.cat);if(S.q)p.set('q',S.q);try{let r=await fetch(API+'?'+p);if(!r.ok)throw 0;let d=await r.json();store(d.store||{});cats(d.categories||[]);let x=(d.products||{}).items||[];S.pages=+(d.products||{}).pages||0;$('results').textContent=(+(d.products||{}).total||0)+' منتج';let h=x.map(card).join('');append?$('grid').insertAdjacentHTML('beforeend',h):$('grid').innerHTML=h||'<div class="empty">لا توجد منتجات مطابقة حاليًا.</div>';bind();$('more').style.display=S.page<S.pages?'inline-block':'none'}catch{$('grid').innerHTML='<div class="empty">تعذر تحميل المنتجات الآن. حاول لاحقًا.</div>';$('more').style.display='none'}finally{S.busy=false;renderCart()}}function add(p){if(!p)return;let x=S.cart.find(v=>+v.id===+p.id);x?x.qty=Math.min(20,+x.qty+1):S.cart.push({id:+p.id,name:p.name,price:+p.price,qty:1});save();note('تمت إضافة المنتج إلى السلة')}function renderCart(){$('count').textContent=S.cart.reduce((n,x)=>n+(+x.qty||1),0);$('items').innerHTML=S.cart.length?S.cart.map((x,i)=>`<div class="item"><div><b>${esc(x.name)}</b><small>${+x.qty} × ${esc(money(x.price))}</small></div><button class="del" data-del="${i}">حذف</button></div>`).join(''):'<div class="empty">السلة فارغة.</div>';document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{S.cart.splice(+b.dataset.del,1);save()});$('total').textContent=money(S.cart.reduce((n,x)=>n+(+x.price)*(+x.qty),0))}function drawer(on){$('drawer').classList.toggle('on',on);$('overlay').classList.toggle('on',on)}async function checkout(){if(!S.cart.length)return note('أضف منتجًا إلى السلة أولًا');let text=['طلب من موقع '+S.store.name,'',...S.cart.map((x,i)=>(i+1)+'. '+x.name+' × '+x.qty),'','الإجمالي: '+$('total').textContent].join('\n');try{await navigator.clipboard.writeText(text);note('تم نسخ ملخص الطلب')}catch{}window.open(tg(),'_blank','noopener')}let t;$('q').oninput=e=>{clearTimeout(t);t=setTimeout(()=>{S.q=e.target.value.trim();S.page=1;load(false)},350)};$('cur').onchange=e=>{S.cur=e.target.value;localStorage.setItem('uchiha_currency',S.cur);renderCart();document.querySelectorAll('[data-buy]').length&&load(false)};$('browse').onclick=()=>$('products').scrollIntoView();$('telegram').onclick=()=>window.open(tg(),'_blank','noopener');$('cartOpen').onclick=()=>drawer(true);$('cartClose').onclick=()=>drawer(false);$('overlay').onclick=()=>drawer(false);$('more').onclick=()=>{if(S.page<S.pages){S.page++;load(true)}};$('checkout').onclick=checkout;$('year').textContent=new Date().getFullYear();renderCart();load(false)})();
</script></body></html>"""
